<?php
declare(strict_types=1);
require_once __DIR__.'/tenant.php';
require_once __DIR__.'/activity.php';
$user=requireLogin();$isAdmin=(string)($user['role']??'')==='admin';$db=db(loadConfigCompat(tenantPrivateFile('config.php')));$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        if(!$isAdmin)throw new RuntimeException('Alleen de administrator kan het wijzigingslogboek aanpassen.');
        verifyCsrf();$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
        if($action==='delete'){
            if($id<1)throw new RuntimeException('Logboekregel ontbreekt.');
            $stmt=$db->prepare('DELETE FROM VveGuiVersielog WHERE VersieLogID=?');$stmt->execute([$id]);
            recordActivity($db,$user,'versielog-verwijderd','instellingen','VveGuiVersielog',(string)$id,'Versielogregel verwijderd.');$message='Logboekregel verwijderd.';
        }else{
            $version=trim((string)($_POST['version']??''));$date=trim((string)($_POST['date']??''));$description=trim((string)($_POST['description']??''));
            if($version===''||mb_strlen($version)>32)throw new RuntimeException('Vul een versienummer van maximaal 32 tekens in.');
            if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Vul een geldige versiedatum in.');
            [$year,$month,$day]=array_map('intval',explode('-',$date));if(!checkdate($month,$day,$year))throw new RuntimeException('Vul een geldige versiedatum in.');
            if($description===''||mb_strlen($description)>20000)throw new RuntimeException('Vul een omschrijving van maximaal 20.000 tekens in.');
            $now=date('Y-m-d H:i:s');$who=(string)($user['username']??'admin');
            if($id){$stmt=$db->prepare('UPDATE VveGuiVersielog SET Versienummer=?,Versiedatum=?,Omschrijving=?,vvegui_modified_at=?,vvegui_modified_by=? WHERE VersieLogID=?');$stmt->execute([$version,$date,$description,$now,$who,$id]);}
            else{$stmt=$db->prepare('INSERT INTO VveGuiVersielog (Versienummer,Versiedatum,Omschrijving,vvegui_modified_at,vvegui_modified_by) VALUES (?,?,?,?,?)');$stmt->execute([$version,$date,$description,$now,$who]);$id=(int)$db->lastInsertId();}
            recordActivity($db,$user,'versielog-opgeslagen','instellingen','VveGuiVersielog',(string)$id,'Versie '.$version.' opgeslagen.');$message='Wijzigingen bij versie '.$version.' opgeslagen.';
        }
    }catch(Throwable $exception){$error=$exception instanceof RuntimeException?$exception->getMessage():'Opslaan is mislukt. Referentie: '.securityIncident($exception);}
}
$rows=$db->query('SELECT * FROM VveGuiVersielog ORDER BY Versiedatum DESC,VersieLogID DESC')->fetchAll(PDO::FETCH_ASSOC);
function vh(string $value):string{return htmlspecialchars($value,ENT_QUOTES,'UTF-8');}
