</style></head><body><header class="top"><img class="logo" src="logo.png" alt="VvE-logo"><div class="brand"><h1><?=tenantNameHtml()?></h1><small>Uw VvE · Wijzigingslogboek</small></div><div class="status"><strong>Verbonden</strong><span><?= $isAdmin?'Beheer':'Alleen-lezen' ?></span><div class="userbar"><span class="badge">👤 <?=vh((string)$user['name'])?> · <?=vh((string)$user['role'])?></span><a class="badge" href="version_log.php">GUI V8.60</a><a class="topbtn" href="./">🗃 Database</a><?php if($isAdmin):?><a class="topbtn" href="settings.php">⚙ Instellingen</a><?php endif;?></div></div></header><main class="wrap"><?php if($isAdmin):?><nav class="tabs"><a href="settings.php">Dropdowns</a><a href="user_management.php">👥 Gebruikers</a><a href="email_settings.php">✉ E-mail</a><a href="ai_settings.php">AI</a><a href="backup_settings.php">Back-ups</a><a href="activity_log.php">Activiteiten</a><a class="active" href="version_log.php">Versies</a></nav><?php endif;?><?php if($message):?><div class="ok">✓ <?=vh($message)?></div><?php endif;?><?php if($error):?><div class="err">⚠ <?=vh($error)?></div><?php endif;?>
<?php if($isAdmin):?><section class="card"><div class="head"><span>Nieuwe versie vastleggen</span></div><form class="body" method="post"><input type="hidden" name="csrf" value="<?=vh(csrfToken())?>"><input type="hidden" name="action" value="save"><div class="form-grid"><div class="field"><label for="version">Versienummer</label><input id="version" name="version" maxlength="32" placeholder="Bijv. 8.51" required></div><div class="field"><label for="date">Versiedatum</label><input id="date" name="date" type="date" value="<?=date('Y-m-d')?>" required></div><div class="field full"><label for="description">Omschrijving van wijzigingen</label><textarea id="description" name="description" maxlength="20000" placeholder="Beschrijf duidelijk wat in deze versie is toegevoegd, gewijzigd of opgelost." required></textarea></div></div><div class="actions"><button class="btn primary" type="submit">💾 Versie toevoegen</button></div></form></section><?php endif;?>
<?php if(!$rows):?><div class="empty">Er zijn nog geen versiewijzigingen vastgelegd.</div><?php endif;?><?php foreach($rows as $row):?><section class="card"><div class="head"><span class="version">GUI v<?=vh((string)$row['Versienummer'])?></span><span class="date"><?=vh(date('d-m-Y',strtotime((string)$row['Versiedatum'])))?></span></div><?php if($isAdmin):?><form class="body" method="post"><input type="hidden" name="csrf" value="<?=vh(csrfToken())?>"><input type="hidden" name="id" value="<?=(int)$row['VersieLogID']?>"><div class="form-grid"><div class="field"><label>Versienummer</label><input name="version" maxlength="32" value="<?=vh((string)$row['Versienummer'])?>" required></div><div class="field"><label>Versiedatum</label><input name="date" type="date" value="<?=vh((string)$row['Versiedatum'])?>" required></div><div class="field full"><label>Omschrijving</label><textarea name="description" maxlength="20000" required><?=vh((string)$row['Omschrijving'])?></textarea></div></div><div class="meta">Laatst gewijzigd op <?=vh((string)$row['vvegui_modified_at'])?> door <?=vh((string)$row['vvegui_modified_by'])?></div><div class="actions"><button class="btn delete" type="submit" name="action" value="delete" onclick="return confirm('Deze logboekregel verwijderen?')">🗑 Wissen</button><button class="btn primary" type="submit" name="action" value="save">💾 Opslaan</button></div></form><?php else:?><div class="body"><div class="description"><?=vh((string)$row['Omschrijving'])?></div></div><?php endif;?></section><?php endforeach;?></main></body></html>
